"""Mutation test of the v27.1 financial code. Each mutation is applied to a scratch COPY of the tree, the v27.1 suites run,
and the mutation must be detected (at least one suite fails). Usage: python tests/v271/mutation_v271.py <scratch_copy_root> <out.json>
underwrite27.js is regenerated by tools/build_underwrite27.py, so waterfall mutations are applied to the built file directly."""
import json, subprocess, sys, time
from pathlib import Path
R = Path(sys.argv[1]).resolve(); OUT = Path(sys.argv[2])
SUITES = ['tests.v271.oracle_waterfall', 'tests.v271.test_schedule_parity', 'tests.v271.test_core_scientific']
M = [
 ('W01 cash may go negative (no floor on payment pool)', 'engine/underwrite27.js', "const pay=due=>{const p=Math.min(Math.max(0,due),Math.max(0,pool));pool-=p;return p};", "const pay=due=>{const p=Math.max(0,due);pool-=p;return p};"),
 ('W02 arrears paid from all cash, not cash above minimum liquidity', 'engine/underwrite27.js', "let avail=Math.max(0,cash-a.minLiquidity);", "let avail=Math.max(0,cash);"),
 ('W03 unpaid interest silently dropped', 'engine/underwrite27.js', "else{uiS+=seniorIntUnpaid;uiM+=mezzIntUnpaid}", "else{}"),
 ('W04 PIK allowed without instrument term', 'engine/underwrite27.js', "if(a.unpaidInterestPolicy==='pik'&&a.pikPermittedByInstrument!==true)", "if(false)"),
 ('W05 configured priority ignored', 'engine/underwrite27.js', "for(const k of a.debtServicePriority){let p=pay(dsDue[k])", "for(const k of ['seniorInterest','seniorPrincipal','mezzInterest','mezzPrincipal']){let p=pay(dsDue[k])"),
 ('W06 dsra_only may use base reserve', 'engine/underwrite27.js', ":Math.max(0,reserve-used-a.reserveTargetM);", ":Math.max(0,reserve-used);"),
 ('W07 exit pays principal before unpaid interest', 'engine/underwrite27.js', "if(k==='seniorInterest'){const p=take(uiS);uiS-=p;exitInterestPaid+=p}", "if(k==='seniorInterest'){}"),
 ('W08 distributions not locked by arrears', 'engine/underwrite27.js', "||arrearsOutstanding||", "||false||"),
 ('W09 default interest on full principal', 'engine/underwrite27.js', "const defaultIntSenior=(uiS+pdS)*dRate", "const defaultIntSenior=(uiS+debt)*dRate"),
 ('W10 matured principal not made past due', 'engine/underwrite27.js', "if(maturedNow){pdS=debt;pdM=mezz}", "if(maturedNow){}"),
 ('S01 independent drivers summed', 'server/schedule27.py', "effective = max(d['months'] for d in drivers)", "effective = sum(d['months'] for d in drivers)"),
 ('S02 dependent delays not accumulated', 'server/schedule27.py', "memo[mid] = up + own(m)", "memo[mid] = max(up, own(m))"),
 ('S03 float ignored', 'server/schedule27.py', "'cod_impact_months': max(0, s - fl),", "'cod_impact_months': s,"),
 ('S04 path estimate added', 'server/schedule27.py', "effective = max(d['months'] for d in drivers)", "effective = max(d['months'] for d in drivers[1:]) + drivers[0]['months']"),
 ('N01 day count actual/360 in 30/360 branch', 'engine/fixed_note27.cjs', "if (dc !== '30/360') throw Error('Unsupported dayCount ' + dc);", "return (b - a) / 864e5 / 360;"),
 ('N02 amortisation on outstanding not original principal', 'engine/fixed_note27.cjs', "const scheduled = amortising ? Math.min(out, inst) : 0;", "const scheduled = amortising ? Math.min(out, out * pct / 100 / per) : 0;"),
 ('N03 OID ignored in net proceeds', 'engine/fixed_note27.cjs', "const netProceeds = P * price / 100 - costs", "const netProceeds = P - costs"),
 ('T01 trigger uses 14 days', 'server/transaction271.py', "+ timedelta(days=15)", "+ timedelta(days=14)"),
]
def suites():
    failing = []
    for s in SUITES:
        p = subprocess.run([sys.executable, '-m', 'unittest', s], cwd=R, capture_output=True, text=True, timeout=600)
        if p.returncode: failing.append(s)
    return failing
base = suites(); res = {'baseline_failing': base, 'mutations': []}
print('baseline failing:', base, flush=True)
for name, rel, old, new in M:
    f = R / rel; orig = f.read_text()
    if orig.count(old) != 1: res['mutations'].append({'name': name, 'error': f'pattern count {orig.count(old)}'}); print('SKIP', name, flush=True); continue
    f.write_text(orig.replace(old, new))
    try: fails = suites()
    finally: f.write_text(orig)
    res['mutations'].append({'name': name, 'file': rel, 'detected': bool(fails), 'detected_by': fails}); print(('DETECTED ' if fails else 'MISSED   ') + name, fails, flush=True)
res['detected'] = sum(1 for m in res['mutations'] if m.get('detected')); res['total'] = len(M)
OUT.write_text(json.dumps(res, indent=1)); print(res['detected'], '/', res['total'])
